PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA busy_timeout = 3000;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL, color TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS merchants(id TEXT PRIMARY KEY, name TEXT NOT NULL, fictional INTEGER NOT NULL CHECK(fictional = 1));
CREATE TABLE IF NOT EXISTS merchant_packages(id TEXT PRIMARY KEY, merchant_id TEXT NOT NULL REFERENCES merchants(id), data_json TEXT NOT NULL CHECK(json_valid(data_json)));
CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY, name TEXT NOT NULL, merchant_id TEXT NOT NULL REFERENCES merchants(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS group_members(group_id TEXT NOT NULL REFERENCES groups(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('ORGANIZER','MEMBER')), PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS purchase_goals(id TEXT PRIMARY KEY, group_id TEXT NOT NULL UNIQUE REFERENCES groups(id), description TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision >= 1), state TEXT NOT NULL CHECK(state IN ('DRAFT','COLLECTING_CONSTRAINTS','SOLVING','PROPOSED','AWAITING_COMMITMENTS','READY_TO_CAPTURE','CAPTURING','CONFIRMED','PROPOSAL_STALE','REPLAN_REQUIRED','CAPTURE_FAILED','COMPENSATING','FAILED')));
CREATE TABLE IF NOT EXISTS constraints(group_id TEXT NOT NULL, user_id TEXT NOT NULL, statement TEXT NOT NULL, parsed_json TEXT NOT NULL CHECK(json_valid(parsed_json)), confirmed INTEGER NOT NULL CHECK(confirmed IN (0,1)), version INTEGER NOT NULL CHECK(version >= 1), source TEXT NOT NULL CHECK(source IN ('SEED','OPENAI','OFFLINE_DEMO')), updated_at TEXT NOT NULL, PRIMARY KEY(group_id,user_id), FOREIGN KEY(group_id,user_id) REFERENCES group_members(group_id,user_id));
CREATE TABLE IF NOT EXISTS constraint_drafts(id TEXT PRIMARY KEY, group_id TEXT NOT NULL, user_id TEXT NOT NULL, goal_revision INTEGER NOT NULL, statement TEXT NOT NULL, parsed_json TEXT NOT NULL CHECK(json_valid(parsed_json)), source TEXT NOT NULL CHECK(source IN ('OPENAI','OFFLINE_DEMO')), created_at TEXT NOT NULL, FOREIGN KEY(group_id,user_id) REFERENCES group_members(group_id,user_id));
CREATE TABLE IF NOT EXISTS proposals(id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES purchase_goals(id), revision INTEGER NOT NULL, package_id TEXT REFERENCES merchant_packages(id), state TEXT NOT NULL CHECK(state IN ('PROPOSED','REPLAN_REQUIRED','PROPOSAL_STALE')), result_json TEXT NOT NULL CHECK(json_valid(result_json)), explanation TEXT NOT NULL, explanation_source TEXT NOT NULL CHECK(explanation_source IN ('OPENAI','OFFLINE_DEMO')), created_at TEXT NOT NULL, UNIQUE(goal_id,revision));
CREATE TABLE IF NOT EXISTS proposal_allocations(id TEXT PRIMARY KEY, proposal_id TEXT NOT NULL REFERENCES proposals(id), user_id TEXT NOT NULL REFERENCES users(id), share_cents INTEGER NOT NULL CHECK(share_cents >= 0), components_json TEXT NOT NULL CHECK(json_valid(components_json)), UNIQUE(proposal_id,user_id));
CREATE TABLE IF NOT EXISTS commitments(id TEXT PRIMARY KEY, allocation_id TEXT NOT NULL UNIQUE REFERENCES proposal_allocations(id), state TEXT NOT NULL CHECK(state IN ('NOT_STARTED','ORDER_CREATED','PAYER_APPROVED','AUTHORIZED','CAPTURED','VOIDED','REFUNDED','FAILED','STALE')), authorized_ceiling_cents INTEGER NOT NULL CHECK(authorized_ceiling_cents >= 0), captured_cents INTEGER NOT NULL DEFAULT 0 CHECK(captured_cents >= 0 AND captured_cents <= authorized_ceiling_cents), paypal_order_id TEXT UNIQUE, paypal_authorization_id TEXT UNIQUE, paypal_capture_id TEXT UNIQUE, expires_at TEXT, request_key TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS payment_events(id TEXT PRIMARY KEY, commitment_id TEXT NOT NULL REFERENCES commitments(id), provider_event_id TEXT UNIQUE, operation TEXT NOT NULL, status TEXT NOT NULL, request_key TEXT, debug_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS merchant_offers(id TEXT PRIMARY KEY, merchant_id TEXT NOT NULL REFERENCES merchants(id), version INTEGER NOT NULL, discount_basis_points INTEGER NOT NULL CHECK(discount_basis_points BETWEEN 0 AND 10000), state TEXT NOT NULL CHECK(state IN ('DRAFT','PUBLISHED','WITHDRAWN')), approved_by TEXT, published_at TEXT);
CREATE TABLE IF NOT EXISTS offer_simulations(id TEXT PRIMARY KEY, offer_id TEXT REFERENCES merchant_offers(id), merchant_id TEXT NOT NULL REFERENCES merchants(id), aggregate_json TEXT NOT NULL CHECK(json_valid(aggregate_json)), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, revision INTEGER, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS demo_sessions(id TEXT PRIMARY KEY, group_id TEXT REFERENCES groups(id), persona TEXT NOT NULL CHECK(persona IN ('kelly','lawrence','sarah','alex','merchant')), csrf_token TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS proposal_goal_revision ON proposals(goal_id,revision DESC);
CREATE INDEX IF NOT EXISTS audit_entity_time ON audit_events(entity_id,created_at);
